vec3 dy = ( GetBlur1(uv + vec2( 0.0 , 1.0 )*d) - GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
ret.y = tex2d(sampler_fc_main, uv + vec2(dx.y,dy.y)*(vec2(1.0)/uTexSize)).y;
vec2 dither_uv = uv_orig*uTexSize.xy*texsize_noise_lq.zw * 1.2 + rand_frame.xy;
ret.y += (texture(sampler_noise_lq, dither_uv).xyz-0.5) *0.04 - 0.002;
ret.y += GetBlur1(uv_orig).x*0.1;
ret.z = mix(tex2d(sampler_fc_heart,uv - vec2(dx.y,dy.y)*0.1).y,
tex2d(sampler_fc_heart,uv - vec2(dx.y,dy.y)*0.1).z,
audioLowSmooth*0.3);
}

