vec3 dy = ( GetBlur1(uv+vec2( 0.0 , 1.0 )*d)-GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
ret = mix(tex2d(sampler_fc_clouds2, uv+vec2(dx.y,dy.y)-vec2(dx.x,dy.x)-vec2(dx.z,dy.z) * 2.0),
tex2d(sampler_fc_clouds,  uv-vec2(dx.y,dy.y)-vec2(dx.x,dy.x)+vec2(dx.z,dy.z)),
GetBlur1(uv).y);;
ret = mix(ret,vec3( 1.0 , 2.0 , 3.0),GetBlur2(uv - vec2(dx.y,dy.y)).x*0.5);
ret = mix(ret,vec3( 2.0 , 1.0 , 0.0),GetPixel(uv).z*0.4);
ret = mix(ret, 0.0 ,GetPixel(uv).x*0.5);
}

